    CreatePlatformEndpointInput.add_member(:token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Token', traits: {"smithy.api#documentation" => "<p>Unique identifier created by the notification service for an app on a device. The\n            specific name for Token will vary, depending on which notification service is being\n            used. For example, when using APNS as the notification service, you need the device\n            token. Alternatively, when using GCM (Firebase Cloud Messaging) or ADM, the device token\n            equivalent is called the registration ID.</p>", "smithy.api#required" => {}}))
