    PublishBatchRequestEntry.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>An identifier for the message in this batch.</p>\n         <note>\n            <p>The <code>Ids</code> of a batch request must be unique within a request. </p>\n            <p>This identifier can have up to 80 characters. The following characters are\n                accepted: alphanumeric characters, hyphens(-), and underscores (_). </p>\n         </note>", "smithy.api#required" => {}}))
    PublishBatchRequestEntry.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: Message, location_name: 'Message', traits: {"smithy.api#documentation" => "<p>The body of the message.</p>", "smithy.api#required" => {}}))
