    RemovePermissionInput.add_member(:label, Smithy::Schema::Shapes::ShapeRef.new(shape: Label, location_name: 'Label', traits: {"smithy.api#documentation" => "<p>The unique label of the statement you want to remove.</p>", "smithy.api#required" => {}}))
