    RouteType.add_member(:promotional, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Promotional', traits: {"smithy.api#enumValue" => "Promotional"}))
