    SMSSandboxPhoneNumber.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: SMSSandboxPhoneNumberVerificationStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The destination phone number's verification status.</p>"}))
    SMSSandboxPhoneNumber.type = Types::SMSSandboxPhoneNumber
