    SubscribeResponse.add_member(:subscription_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: SubscriptionARN, location_name: 'SubscriptionArn', traits: {"smithy.api#documentation" => "<p>The ARN of the subscription if it is confirmed, or the string \"pending confirmation\"\n            if the subscription requires confirmation. However, if the API request parameter\n                <code>ReturnSubscriptionArn</code> is true, then the value is always the\n            subscription ARN, even if the subscription requires confirmation.</p>"}))
